package com.nbi.layered.model;

import jakarta.persistence.*;
import java.math.BigDecimal;
import java.util.*;

// ENTITY: JPA-managed, maps to a table, stays INTERNAL (never returned).
@Entity
@Table(name = "accounts")
public class Account {
    @Id private String id;
    private String holderName;
    private BigDecimal balance;
    @Version private long version;                 // optimistic locking
    @ElementCollection private List<String> txnIds = new ArrayList<>(); // lazy by default

    protected Account() {}
    public Account(String id, String holderName, BigDecimal balance) {
            this.id = id;
            this.holderName = holderName
            this.balance = balance;
    }
    public String getId() { return id; }
    public String getHolderName() { return holderName; }
    public BigDecimal getBalance() { return balance; }
    public void setBalance(BigDecimal b) { this.balance = b; }
}
```

