package com.nbi.layered.domain;

import java.math.*;

// POJO value object: framework-free, holds BUSINESS LOGIC, easy to unit test.
public class Money {
    private final BigDecimal amount;
    public Money(BigDecimal amount) {
        if (amount.signum() < 0) throw new IllegalArgumentException("negative money");
        this.amount = amount.setScale(2, RoundingMode.HALF_UP);
    }
    public Money applyInterest(BigDecimal annualRatePercent) {
        BigDecimal interest = amount.multiply(annualRatePercent)
                .divide(new BigDecimal("100"), 2, RoundingMode.HALF_UP);
        return new Money(amount.add(interest)); // logic lives in the POJO
    }
    public BigDecimal value() { return amount; }
}
```

