// ─── File: src/main/java/com/nbi/layered/service/AccountService.java ───
package com.nbi.layered.service;

import com.nbi.layered.domain.Money;
import com.nbi.layered.dto.*;
import com.nbi.layered.model.Account;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;

@Service
public class AccountService {
    private final Map<String, Account> repo = new HashMap<>(); // stands in for JpaRepository

    // Receives a DTO → builds an ENTITY → returns a DTO. Entity never escapes.
    public AccountResponse open(OpenAccountRequest r) {
        String id = "ACC-" + UUID.randomUUID().toString().substring(0, 6);
        Account entity = new Account(id, r.holderName(), r.openingBalance());
        repo.put(id, entity);
        return toResponse(entity);
    }

    // Uses the POJO value object for framework-free business logic.
    public AccountResponse addYearlyInterest(String id, BigDecimal ratePercent) {
        Account entity = repo.get(id);
        Money newBalance = new Money(entity.getBalance()).applyInterest(ratePercent);
        entity.setBalance(newBalance.value()); // managed entity: change persisted
        return toResponse(entity);
    }

    public Optional<AccountResponse> find(String id) {
        return Optional.ofNullable(repo.get(id)).map(this::toResponse);
    }

    private AccountResponse toResponse(Account a) {
        return new AccountResponse(a.getId(), a.getHolderName(), a.getBalance());
    }
}
```

