// ─── File: src/main/java/com/nbi/layered/controller/AccountController.java ───
package com.nbi.layered.controller;

import com.nbi.layered.dto.*;
import com.nbi.layered.service.AccountService;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import jakarta.validation.Valid;
import java.math.BigDecimal;
import java.net.URI;

@RestController
@RequestMapping("/api/v1/accounts")
public class AccountController {

    private final AccountService service;
    public AccountController(AccountService service) { this.service = service; }

    @PostMapping
    public ResponseEntity<AccountResponse> open(@Valid @RequestBody OpenAccountRequest r) {
        AccountResponse resp = service.open(r);
        return ResponseEntity.created(URI.create("/api/v1/accounts/" + resp.accountId())).body(resp);
    }

    @PostMapping("/{id}/interest")
    public ResponseEntity<AccountResponse> interest(@PathVariable String id,
            @RequestParam BigDecimal ratePercent) {
        return ResponseEntity.ok(service.addYearlyInterest(id, ratePercent));
    }
}
```
